+function requestLanguage(headers) {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "accept-language");
+  let language = config.defaultLanguage;
+  let bestWeight = 0;
+  for (const entry of String(header?.[1] ?? "").split(",")) {
+    const match = /^([a-z]+)(?:-[a-z0-9]{1,8})*(?:\s*;\s*q\s*=\s*(0(?:\.\d{0,3})?|1(?:\.0{0,3})?))?$/i.exec(entry.trim());
+    if (!match) continue;
+    const candidate = match[1].toLowerCase();
+    const weight = Number(match[2] ?? 1);
+    if (LANGUAGES.includes(candidate) && weight > bestWeight) {
+      language = candidate;
+      bestWeight = weight;
+    }
+  }
+  return language;
+}
